function readNode(name) {
  try { return $(name).first().json || {}; } catch (e) { return {}; }
}
const normalizado = readNode('Normalizar Classificação');
const pgErro = readNode('PG: Erro IA Classif');
const preparado = readNode('Preparar Classificação');
const chamadoBase = normalizado.chamado || preparado.chamado || {};
const id = Number(chamadoBase.id || pgErro.id || 0);
const erro = String(
  normalizado.mensagem_erro ||
  normalizado.erro ||
  normalizado.error ||
  pgErro.ultimo_erro_ia ||
  'Resposta invalida ou indisponibilidade da IA de classificacao'
);
const tentativas = Number(
  pgErro.tentativas_ia_classificacao ??
  normalizado.tentativas_ia_classificacao ??
  chamadoBase.tentativas_ia_classificacao ??
  0
);
const tituloOriginal = String(chamadoBase.titulo || chamadoBase.name || ('Chamado #' + (id || 'sem ID'))).trim();
const tituloSemTag = tituloOriginal.replace(/^\[Erro IA\]\s*/i, '').trim() || ('Chamado #' + (id || 'sem ID'));
const tituloNovo = ('[Erro IA] ' + tituloSemTag).slice(0, 250);
const aviso = [
  '[TRIAGEM_IA][ERRO_CLASSIFICACAO]',
  'A automacao nao conseguiu classificar este chamado apos o limite de tentativas da IA.',
  'O chamado foi mantido como Pendente para revisao manual do fiscal no GLPI.',
  '',
  'ID do chamado: ' + (id || 'N/A'),
  'Titulo original: ' + tituloOriginal,
  'Tentativas de IA: ' + (Number.isFinite(tentativas) ? tentativas : 'N/A'),
  'Erro registrado: ' + erro,
  '',
  'Acao necessaria: fiscal deve assumir a triagem e definir manualmente o encaminhamento.'
].join('\n');
console.log('[WF03][LOG] Erro classificacao final preparado #' + (id || 'N/A') + ' tentativas=' + (Number.isFinite(tentativas) ? tentativas : 'N/A'));
return [{json:{
  chamado:{...chamadoBase, id, titulo:tituloNovo, status_num:4, status_nome:'Pendente'},
  titulo_novo:tituloNovo,
  aviso_glpi:aviso,
  erro,
  tentativas
}}];

